 "content": "from collections import deque


def transform(grid):
    """Remove the 4-connected nonzero object containing the fewest 9 cells."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            objects.append((sum(grid[y][x] == 9 for y, x in cells), cells))
    if not objects:
        return [row[:] for row in grid]
    _, target = min(objects, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = 0
    return out


